  // Source properties are captured once. Learner storage and entered text are never traversed.
  const entries = [], seen = new WeakSet();
  let language = 'he';
  function register(object) {
    if (!object || typeof object !== 'object' || seen.has(object)) return;
    seen.add(object);
    for (const [key,value] of Object.entries(object)) {
      if (typeof value === 'string') entries.push([object,key,value]);
      else register(value);
    }
  }
